import{_ as t,o,c as a,a2 as r}from"./chunks/framework.vLhlLNVn.js";const h=JSON.parse('{"title":"Security Overview","description":"","frontmatter":{},"headers":[],"relativePath":"security/overview.md","filePath":"security/overview.md","lastUpdated":1795273079000}'),i={name:"security/overview.md"};function d(n,e,c,s,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="security-overview" tabindex="-1">Security Overview <a class="header-anchor" href="#security-overview" aria-label="Permalink to &quot;Security Overview&quot;">​</a></h1><p>JetPack exposes local native hardware and OS-level compute to web applications running inside untrusted browser origins. Because a local daemon listening on <code>127.0.0.1</code> is an attractive target for malicious websites, DNS rebinding, browser extensions, and supply-chain tampering, JetPack enforces defense-in-depth across four distinct security boundaries.</p><h2 id="threat-model-trust-boundaries" tabindex="-1">Threat Model &amp; Trust Boundaries <a class="header-anchor" href="#threat-model-trust-boundaries" aria-label="Permalink to &quot;Threat Model &amp; Trust Boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Boundary</th><th style="text-align:left;">Threat Addressed</th><th style="text-align:left;">Enforcement Mechanism</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Browser &lt;-&gt; Daemon Transport</strong></td><td style="text-align:left;">Cross-site WebSocket hijacking, DNS rebinding, rogue local tabs, plaintext inspection</td><td style="text-align:left;">Strict <code>127.0.0.1</code> bind, HTTP Upgrade <code>Origin</code> allowlist + W3C PNA, Out-of-Band <code>jetpack://pair</code> + native OS dialog, <code>X25519</code> + <code>Ed25519</code> handshake, <code>ChaCha20-Poly1305</code> encrypted framing, <code>1003</code> close on JSON/text frames</td></tr><tr><td style="text-align:left;"><strong>2. At-Rest Credential &amp; Consent Store</strong></td><td style="text-align:left;">Local unprivileged malware or SQLite tools reading paired keys or authorized folder paths</td><td style="text-align:left;">256-bit <code>ChaCha20-Poly1305</code> (AEAD) encrypted SQLite container (<code>paired_clients.db</code>) with master key stored exclusively in OS Vault (<code>DPAPI</code> / <code>Keychain</code> / <code>Secret Service</code>), Unix <code>0700</code> / <code>0600</code> directory and file permissions</td></tr><tr><td style="text-align:left;"><strong>3. Daemon &lt;-&gt; Native Worker Sandbox</strong></td><td style="text-align:left;">Malicious or compromised AI/media worker reading user documents (<code>~/Documents</code>, <code>~/.ssh</code>), spawning hidden background processes, or exfiltrating data over the internet</td><td style="text-align:left;">Default-deny OS kernel sandboxes (<code>Windows AppContainer + Job Objects</code>, <code>macOS Seatbelt</code>, <code>Linux bwrap + Landlock LSM</code>), user-selected <code>[volumes]</code> via native OS <code>rfd</code> picker, and an in-daemon Userspace Network Proxy filtered by <code>permissions.network_allowlist</code></td></tr><tr><td style="text-align:left;"><strong>4. App Store &amp; Supply Chain</strong></td><td style="text-align:left;">Tampered catalog entries, App ID spoofing (<code>io.jetpack.*</code>), registry redirection, Tar-Slip extraction, linker injection (<code>LD_PRELOAD</code>)</td><td style="text-align:left;">Compiled-in <code>CATALOG_VERIFY_PUBKEY</code> (<code>Ed25519</code>), <code>manifest_sha256</code> pinning, per-app <code>allowed_origins</code> enforcement, SHA-256 CAS verification, Tar-Slip rejection, and <code>#[serde(deny_unknown_fields)]</code> manifest validation</td></tr></tbody></table><h2 id="architectural-security-guarantees" tabindex="-1">Architectural Security Guarantees <a class="header-anchor" href="#architectural-security-guarantees" aria-label="Permalink to &quot;Architectural Security Guarantees&quot;">​</a></h2><h3 id="rust-as-the-sole-gatekeeper" tabindex="-1">Rust as the Sole Gatekeeper <a class="header-anchor" href="#rust-as-the-sole-gatekeeper" aria-label="Permalink to &quot;Rust as the Sole Gatekeeper&quot;">​</a></h3><p>Browser code (<code>@jetpack/client</code> / <code>jetpack-wasm</code>) <strong>never</strong> opens sockets or named pipes directly to Python or C++ workers. All external traffic terminates inside <code>jetpack-daemon</code> (<code>crates/jetpack-daemon/src/ws_server.rs</code>), which:</p><ol><li>Refuses to bind to <code>0.0.0.0</code>, <code>::</code>, or any non-loopback IP address before opening a TCP listener.</li><li>Validates the normalized HTTP <code>Origin</code> header on both <code>OPTIONS</code> Private Network Access preflights and WebSocket <code>GET</code> upgrades against <code>paired_clients.db</code> (or the daemon&#39;s own Control Center origin <code>http://127.0.0.1:&lt;port&gt;</code>). Rejects unknown or missing origins with <code>HTTP/1.1 403 Forbidden</code>.</li><li>Enforces a 5-second post-upgrade cryptographic <code>ClientHello</code> handshake binding the HTTP <code>Origin</code> to <code>ClientHello.origin</code> and the paired <code>Ed25519</code> public key.</li><li>Enforces per-application <code>Origin</code> authorization before <code>&quot;app.launch&quot;</code> or forwarding any frame with <code>target_worker</code> set.</li></ol><h3 id="zero-client-trust-for-host-paths-privileges" tabindex="-1">Zero Client Trust for Host Paths &amp; Privileges <a class="header-anchor" href="#zero-client-trust-for-host-paths-privileges" aria-label="Permalink to &quot;Zero Client Trust for Host Paths &amp; Privileges&quot;">​</a></h3><ul><li>Web clients <strong>cannot</strong> pass absolute host filesystem paths to workers; any path in <code>AppLaunchRequest</code> is ignored/rejected. Host folders for <code>[volumes.&lt;name&gt;]</code> are selected exclusively by the human user through the native OS folder dialog (<code>rfd</code>).</li><li>Web clients <strong>cannot</strong> bypass <code>SignedAppCatalog</code> verification via <code>&quot;settings.set&quot;</code> (<code>developer_mode = true</code> never enables unverified network <code>&quot;app.pull&quot;</code>).</li><li>Local developer apps (<code>--install-local-app</code>) are restricted strictly to non-official IDs (never shadowing <code>SignedAppCatalog</code> entries) and can only be invoked from loopback origins (<code>127.0.0.1</code> / <code>localhost</code>).</li></ul><h2 id="detailed-security-audit-sections" tabindex="-1">Detailed Security Audit Sections <a class="header-anchor" href="#detailed-security-audit-sections" aria-label="Permalink to &quot;Detailed Security Audit Sections&quot;">​</a></h2><ul><li><a href="/security/pairing-and-crypto">Pairing &amp; Cryptography</a>: Out-of-Band <code>jetpack://pair</code>, <code>X25519</code> + <code>Ed25519</code> handshake, <code>ChaCha20-Poly1305</code> framing, and <code>ChaCha20-Poly1305</code> at-rest store + OS Vault key management.</li><li><a href="/security/os-sandboxing">OS Kernel Sandboxing</a>: Platform-by-platform kernel primitives (<code>AppContainer</code>, <code>Seatbelt</code>, <code>bwrap</code> + <code>Landlock LSM</code>) and Userspace Network Proxy filtering.</li><li><a href="/security/signed-catalog">Signed Catalog &amp; Anti-Spoofing</a>: <code>Ed25519</code> root key verification, <code>manifest_sha256</code> pinning, and per-app <code>Origin</code> isolation.</li></ul>',12)])])}const g=t(i,[["render",d]]);export{h as __pageData,g as default};
